parameters.jsCode:
const items = $input.all();

return items.map(item => {
  const ai = item.json.output;

  // Original normalized lead data
  const lead = $("Add Lead Metadata").first().json;

  let score = 0;
  const scoreBreakdown = [];

  if (Number(lead.budget) >= 3000) {
    score += 30;
    scoreBreakdown.push("Budget >= $3000: +30");
  }

  if (ai.intent === "purchase") {
    score += 25;
    scoreBreakdown.push("Purchase intent: +25");
  }

  if (ai.urgency === "high") {
    score += 20;
    scoreBreakdown.push("High urgency: +20");
  }

  if (ai.requirements_clarity === "high") {
    score += 15;
    scoreBreakdown.push("Clear requirements: +15");
  }

  if (lead.company && lead.company !== "Unknown") {
    score += 10;
    scoreBreakdown.push("Known company: +10");
  }

  let leadTemperature;

  if (score >= 80) {
    leadTemperature = "HOT";
  } else if (score >= 50) {
    leadTemperature = "WARM";
  } else {
    leadTemperature = "COLD";
  }

  return {
    json: {
      ...lead,
      aiAnalysis: ai,
      leadScore: score,
      leadTemperature,
      scoreBreakdown
    }
  };
});

