parameters.jsCode:
const callbackData = $json.callback_query.data;

const [action, leadId] = callbackData.split('|');

if (!['approve', 'reject'].includes(action)) {
  throw new Error(`Invalid approval action: ${action}`);
}

if (!leadId) {
  throw new Error('Missing leadId in Telegram callback');
}

return {
  json: {
    action,
    leadId,
    callbackQueryId: $json.callback_query.id,
    chatId: $json.callback_query.message.chat.id,
    messageId: $json.callback_query.message.message_id,
  }
};

